    (@sentinel, @sentinel, CONVERT(xml, N'<event name="blocked_process_report" package="sqlserver" timestamp="2099-12-31T23:59:59.000Z"><data name="duration"><type name="uint64" package="package0"/><value>9046000</value></data><data name="database_id"><type name="int16" package="package0"/><value>0</value></data><data name="object_id"><type name="int32" package="package0"/><value>0</value></data><data name="index_id"><type name="uint32" package="package0"/><value>0</value></data><data name="lock_mode"><type name="lock_mode" package="sqlserver"/><value>0</value><text>NL</text></data><data name="transaction_id"><type name="int64" package="package0"/><value>0</value></data><data name="resource_owner_type"><type name="resource_owner_type" package="sqlserver"/><value>0x00000008</value><text>GENERIC</text></data><data name="blocked_process"><type name="xml" package="package0"/><value><blocked-process-report monitorLoop="184"><blocked-process><process id="process24723709848" taskpriority="0" logused="20000" waittime="9046" schedulerid="1" kpid="5000" status="suspended" spid="61" sbid="2" ecid="0" priority="0" trancount="0" lastbatchstarted="2026-06-14T21:45:12.570" lastbatchcompleted="1900-01-01T00:00:00.570" lastattention="1900-01-01T00:00:00.570" clientapp="Core Microsoft SqlClient Data Provider" hostname="NADAFACCIA" hostpid="22720" loginname="sa" isolationlevel="read uncommitted (1)" xactid="196568" currentdb="6" currentdbname="PerformanceMonitor" lockTimeout="4294967295" clientoption1="671088672" clientoption2="128056"><executionStack><frame line="19" stmtstart="2194" stmtend="5166" sqlhandle="0x020000005aaca308ff748e3ce341135035aa926c858bf2210000000000000000000000000000000000000000"/></executionStack><inputbuf>SELECT 1; /*regression-sample*/</inputbuf></process></blocked-process><blocking-process><process status="suspended" waittime="9034" spid="61" sbid="2" ecid="0" priority="0" trancount="0" lastbatchstarted="2026-06-14T21:45:12.570" lastbatchcompleted="1900-01-01T