/* Run the processor (NULL dates -> auto-derive bounds from the unprocessed rows). */
EXEC collect.process_blocked_process_xml @debug = 1;

/* -------------------------------- assertions -------------------------------- */
SELECT @raw_unprocessed = COUNT(*) FROM collect.blocked_process_xml WHERE event_time = @sentinel AND is_processed = 0;
SELECT @chains = COUNT(*) FROM collect.blocking_BlockedProcessReport WHERE event_time >= '2099-01-01' AND blocking_spid IS NOT NULL;
SELECT @self_chains = COUNT(*) FROM collect.blocking_BlockedProcessReport WHERE event_time >= '2099-01-01' AND blocking_spid = 61;
SELECT TOP 1 @status = collection_status FROM config.collection_log WHERE collector_name = 'process_blocked_process_xml' ORDER BY collection_time DESC;

IF @raw_unprocessed = 0
    PRINT 'PASS 1: both sample events marked processed (self-block drains; no perpetual retry)';
ELSE
BEGIN SET @fail += 1; PRINT 'FAIL 1: a sentinel raw row was left unprocessed (stuck-retry not fixed)'; END;

IF @chains >= 1
    PRINT 'PASS 2: two-session block parsed to a chain (happy path + single-timestamp +1s window)';
ELSE
BEGIN SET @fail += 1; PRINT 'FAIL 2: two-session block did NOT parse - inclusive-window or happy-path regression'; END;

IF @self_chains = 0
    PRINT 'PASS 3: self-block produced no chain (correctly filtered, yet still marked processed)';
ELSE
BEGIN SET @fail += 1; PRINT 'FAIL 3: self-block leaked a chain row (spid 61)'; END;

IF @status = 'SUCCESS'
    PRINT 'PASS 4: collection_log status = SUCCESS (not the old perpetual NO_RESULTS)';
ELSE
BEGIN SET @fail += 1; SET @msg = 'FAIL 4: collection_log status = ' + ISNULL(@status, '(null)') + ' (expected SUCCESS)'; PRINT @msg; END;

/* --------------------------------- cleanup ---------------------------------- */
DELETE FROM collect.blocking_BlockedProcessReport WHERE event_time >= '2099-01-01';
DELETE FROM collect.blocked_process_xml WHERE event_time >= '2099-01-01';

IF @fail = 0
    PRINT '=== RESULT: ALL PASS ===';
ELSE
BEGIN
    SET @msg = '=== RESULT: ' + CONVERT(nvarchar(10), @fail) + ' assertion(s) FAILED ===';
    RAISERROR(@msg, 16, 1);
END;
GO
